tool_input.command:
git log --oneline | head -2 && cat >> src/boxOffice.test.ts <<'EOF'

const MINUTE = 60_000;
const START = 1_000_000;

function setup(overrides: Partial<BoxOfficeOptions> = {}) {
  const clock = { time: START };
  const office = createBoxOffice({
    sections: [
      { id: "A", capacity: 10, priceCents: 5000 },
      { id: "B", capacity: 3, priceCents: 1233 },
    ],
    holdMinutes: 15,
    maxTicketsPerCustomer: 6,
    now: () => clock.time,
    ...overrides,
  });
  return { office, clock };
}

function codeOf(fn: () => unknown): string | undefined {
  try {
    fn();
  } catch (error) {
    if (error instanceof BoxOfficeError) return error.code;
    throw error;
  }
  return undefined;
}

describe("availability", () => {
  test("available returns the capacity of an untouched section", () => {
    const { office } = setup();
    expect(office.available("A")).toBe(10);
    expect(office.available("B")).toBe(3);
  });
});
EOF
sed -i 's/^import { BoxOfficeError } from ".\/boxOffice";/import { BoxOfficeError, createBoxOffice, type BoxOfficeOptions } from ".\/boxOffice";/' src/boxOffice.test.ts
bun test 2>&1 | tail -8

cat >> src/boxOffice.test.ts <<'EOF'

describe("errors", () => {
  test("available rejects an unknown section with UNKNOWN_SECTION", () => {
    const { office } = setup();
    expect(codeOf(() => office.available("Z"))).toBe("UNKNOWN_SECTION");
  });
});
EOF
bun test 2>&1 | grep -E "^\(fail|error:|Expected|Received" | head
